import{_ as e,o as s,c as t,a5 as i}from"./chunks/framework.a5no_H3L.js";const k=JSON.parse('{"title":"近实时搜索","description":"ES 不是实时搜索引擎，而是近实时搜索引擎。文档写入后需要经过 refresh 操作才能被搜索到，默认延迟约 1 秒。","frontmatter":{},"headers":[],"relativePath":"elasticsearch/05-distributed-internals/chapter-06-near-real-time.md","filePath":"elasticsearch/05-distributed-internals/chapter-06-near-real-time.md"}'),n={name:"elasticsearch/05-distributed-internals/chapter-06-near-real-time.md"};function l(r,a,d,h,c,p){return s(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="近实时搜索" tabindex="-1" data-src-line="1" data-src-file="elasticsearch/05-distributed-internals/chapter-06-near-real-time.md">近实时搜索 <a class="header-anchor" href="#近实时搜索" aria-label="Permalink to &quot;近实时搜索&quot;">​</a></h1><h2 id="_1-near-real-time-nrt-机制" tabindex="-1" data-src-line="3" data-src-file="elasticsearch/05-distributed-internals/chapter-06-near-real-time.md">1. Near Real-Time（NRT）机制 <a class="header-anchor" href="#_1-near-real-time-nrt-机制" aria-label="Permalink to &quot;1. Near Real-Time（NRT）机制&quot;">​</a></h2><p data-src-line="5" data-src-file="elasticsearch/05-distributed-internals/chapter-06-near-real-time.md">ES 不是实时搜索引擎，而是近实时搜索引擎。文档写入后需要经过 <code>refresh</code> 操作才能被搜索到，默认延迟约 1 秒。</p><p data-src-line="7" data-src-file="elasticsearch/05-distributed-internals/chapter-06-near-real-time.md">默认 1s 是刷新间隔设置，不代表每个分片始终每秒执行后台刷新。分片进入 search-idle 状态（默认 30 秒无搜索请求）后会暂停后台刷新，直到下一次搜索触发。</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>写入 → Buffer → refresh（默认1s）→ Segment → 可搜索</span></span>
<span class="line"><span>              ↓</span></span>
<span class="line"><span>           Translog（持久化，防止数据丢失）</span></span></code></pre></div><h2 id="_2-refresh-操作" tabindex="-1" data-src-line="15" data-src-file="elasticsearch/05-distributed-internals/chapter-06-near-real-time.md">2. Refresh 操作 <a class="header-anchor" href="#_2-refresh-操作" aria-label="Permalink to &quot;2. Refresh 操作&quot;">​</a></h2><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 手动刷新索引</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">POST /my-index/_refresh</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 设置刷新间隔</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PUT /my-index/_settings</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;index.refresh_interval&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;5s&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 关闭自动刷新（批量写入时）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PUT /my-index/_settings</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;index.refresh_interval&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-1&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><table tabindex="0"><thead data-src-line="34" data-src-file="elasticsearch/05-distributed-internals/chapter-06-near-real-time.md"><tr data-src-line="34" data-src-file="elasticsearch/05-distributed-internals/chapter-06-near-real-time.md"><th style="text-align:left;">refresh_interval</th><th style="text-align:left;">说明</th><th style="text-align:left;">适用场景</th></tr></thead><tbody data-src-line="36" data-src-file="elasticsearch/05-distributed-internals/chapter-06-near-real-time.md"><tr data-src-line="36" data-src-file="elasticsearch/05-distributed-internals/chapter-06-near-real-time.md"><td style="text-align:left;"><code>1s</code>（默认）</td><td style="text-align:left;">默认刷新间隔约 1 秒（search-idle 分片除外）</td><td style="text-align:left;">通用场景</td></tr><tr data-src-line="37" data-src-file="elasticsearch/05-distributed-internals/chapter-06-near-real-time.md"><td style="text-align:left;"><code>5s</code></td><td style="text-align:left;">每 5 秒刷新</td><td style="text-align:left;">写入密集型</td></tr><tr data-src-line="38" data-src-file="elasticsearch/05-distributed-internals/chapter-06-near-real-time.md"><td style="text-align:left;"><code>-1</code></td><td style="text-align:left;">不自动刷新</td><td style="text-align:left;">批量导入</td></tr><tr data-src-line="39" data-src-file="elasticsearch/05-distributed-internals/chapter-06-near-real-time.md"><td style="text-align:left;"><code>null</code></td><td style="text-align:left;">恢复默认</td><td style="text-align:left;">-</td></tr></tbody></table><h2 id="_3-translog-与持久性" tabindex="-1" data-src-line="41" data-src-file="elasticsearch/05-distributed-internals/chapter-06-near-real-time.md">3. Translog 与持久性 <a class="header-anchor" href="#_3-translog-与持久性" aria-label="Permalink to &quot;3. Translog 与持久性&quot;">​</a></h2><p data-src-line="43" data-src-file="elasticsearch/05-distributed-internals/chapter-06-near-real-time.md">Translog 用于恢复尚未通过 Lucene commit 持久化的操作。数据能否在故障后恢复，取决于 Translog 的持久化策略以及操作是否已完成同步：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Translog 配置</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PUT /my-index/_settings</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;index.translog.durability&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;request&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;index.translog.sync_interval&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;5s&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;index.translog.flush_threshold_size&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;512mb&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><table tabindex="0"><thead data-src-line="55" data-src-file="elasticsearch/05-distributed-internals/chapter-06-near-real-time.md"><tr data-src-line="55" data-src-file="elasticsearch/05-distributed-internals/chapter-06-near-real-time.md"><th style="text-align:left;">配置</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="57" data-src-file="elasticsearch/05-distributed-internals/chapter-06-near-real-time.md"><tr data-src-line="57" data-src-file="elasticsearch/05-distributed-internals/chapter-06-near-real-time.md"><td style="text-align:left;"><code>durability: request</code></td><td style="text-align:left;">每个写请求成功返回前，主分片及所有已分配副本分片完成 Translog 的 fsync 和提交（默认）</td></tr><tr data-src-line="58" data-src-file="elasticsearch/05-distributed-internals/chapter-06-near-real-time.md"><td style="text-align:left;"><code>durability: async</code></td><td style="text-align:left;">按 <code>sync_interval</code> 周期 fsync，最近一次同步后尚未持久化的操作可能丢失</td></tr><tr data-src-line="59" data-src-file="elasticsearch/05-distributed-internals/chapter-06-near-real-time.md"><td style="text-align:left;"><code>flush_threshold_size</code></td><td style="text-align:left;">translog 达到此大小后自动 flush</td></tr></tbody></table><h2 id="_4-flush-操作" tabindex="-1" data-src-line="61" data-src-file="elasticsearch/05-distributed-internals/chapter-06-near-real-time.md">4. Flush 操作 <a class="header-anchor" href="#_4-flush-操作" aria-label="Permalink to &quot;4. Flush 操作&quot;">​</a></h2><p data-src-line="63" data-src-file="elasticsearch/05-distributed-internals/chapter-06-near-real-time.md">Flush 的核心是执行一次 Lucene commit，并开启新的 Translog generation，使旧 generation 在满足条件后可以被清理。Refresh 使近期操作对搜索可见，Flush 通过 Lucene commit 持久化索引提交并推进 Translog generation，两者解决的问题不同：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 手动 flush（执行 Lucene commit）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">POST /my-index/_flush</span></span></code></pre></div><h2 id="_5-写入流程时序" tabindex="-1" data-src-line="70" data-src-file="elasticsearch/05-distributed-internals/chapter-06-near-real-time.md">5. 写入流程时序 <a class="header-anchor" href="#_5-写入流程时序" aria-label="Permalink to &quot;5. 写入流程时序&quot;">​</a></h2><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>写入操作</span></span>
<span class="line"><span>   ├── Refresh（默认约 1s）→ 新 Segment → 搜索可见</span></span>
<span class="line"><span>   └── Translog fsync/commit → 写入持久性保障</span></span>
<span class="line"><span>                                    │</span></span>
<span class="line"><span>                                    ▼</span></span>
<span class="line"><span>                Flush：Lucene commit + 开启新 Translog generation</span></span></code></pre></div><p data-src-line="81" data-src-file="elasticsearch/05-distributed-internals/chapter-06-near-real-time.md">Refresh 解决搜索可见性，Translog 解决持久性，二者是相互独立的机制，不构成每次写入必经的固定步骤序列。Flush 不固定时间触发，也不意味着所有 Translog 立即被删除。</p><h2 id="_6-如何让文档立即可搜索" tabindex="-1" data-src-line="83" data-src-file="elasticsearch/05-distributed-internals/chapter-06-near-real-time.md">6. 如何让文档立即可搜索 <a class="header-anchor" href="#_6-如何让文档立即可搜索" aria-label="Permalink to &quot;6. 如何让文档立即可搜索&quot;">​</a></h2><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 方式1：refresh=wait_for，等待下一次 refresh（开销低）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PUT /my-index/_doc/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">?refresh=wait_for</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;title&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;等待搜索可见&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 方式2：refresh=true，强制刷新（写入开销高）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PUT /my-index/_doc/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">?refresh=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;title&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;立即可搜索&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 方式3：写入后手动 refresh</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">POST /my-index/_refresh</span></span></code></pre></div><p data-src-line="102" data-src-file="elasticsearch/05-distributed-internals/chapter-06-near-real-time.md">三种行为有本质区别：默认异步可见（写入即返回，等后台 refresh）、<code>refresh=wait_for</code>（等待下一次 refresh，不主动触发）、<code>refresh=true</code>（主动强制刷新，代价最高）。缩短 <code>refresh_interval</code> 只适用于确实需要整体降低搜索可见延迟的场景，不是单文档即时查询的首选。</p><h2 id="_7-segment-与近实时" tabindex="-1" data-src-line="104" data-src-file="elasticsearch/05-distributed-internals/chapter-06-near-real-time.md">7. Segment 与近实时 <a class="header-anchor" href="#_7-segment-与近实时" aria-label="Permalink to &quot;7. Segment 与近实时&quot;">​</a></h2><p data-src-line="106" data-src-file="elasticsearch/05-distributed-internals/chapter-06-near-real-time.md">每个 Segment 是一个完整的倒排索引，不可变。Refresh 操作创建新的 Segment：</p><table tabindex="0"><thead data-src-line="108" data-src-file="elasticsearch/05-distributed-internals/chapter-06-near-real-time.md"><tr data-src-line="108" data-src-file="elasticsearch/05-distributed-internals/chapter-06-near-real-time.md"><th style="text-align:left;">操作</th><th style="text-align:left;">效果</th></tr></thead><tbody data-src-line="110" data-src-file="elasticsearch/05-distributed-internals/chapter-06-near-real-time.md"><tr data-src-line="110" data-src-file="elasticsearch/05-distributed-internals/chapter-06-near-real-time.md"><td style="text-align:left;">新增文档</td><td style="text-align:left;">写入新 Segment</td></tr><tr data-src-line="111" data-src-file="elasticsearch/05-distributed-internals/chapter-06-near-real-time.md"><td style="text-align:left;">删除文档</td><td style="text-align:left;">标记为已删除，查询时不再返回</td></tr><tr data-src-line="112" data-src-file="elasticsearch/05-distributed-internals/chapter-06-near-real-time.md"><td style="text-align:left;">更新文档</td><td style="text-align:left;">标记旧文档删除 + 写入新 Segment</td></tr><tr data-src-line="113" data-src-file="elasticsearch/05-distributed-internals/chapter-06-near-real-time.md"><td style="text-align:left;">Segment Merge</td><td style="text-align:left;">合并小 Segment，物理删除标记文档</td></tr></tbody></table><h2 id="_8-最佳实践" tabindex="-1" data-src-line="115" data-src-file="elasticsearch/05-distributed-internals/chapter-06-near-real-time.md">8. 最佳实践 <a class="header-anchor" href="#_8-最佳实践" aria-label="Permalink to &quot;8. 最佳实践&quot;">​</a></h2><ul data-src-line="117" data-src-file="elasticsearch/05-distributed-internals/chapter-06-near-real-time.md"><li data-src-line="117" data-src-file="elasticsearch/05-distributed-internals/chapter-06-near-real-time.md">通用场景使用默认 <code>refresh_interval: 1s</code></li><li data-src-line="118" data-src-file="elasticsearch/05-distributed-internals/chapter-06-near-real-time.md">批量写入时临时设为 <code>-1</code>，写完后手动 <code>_refresh</code></li><li data-src-line="119" data-src-file="elasticsearch/05-distributed-internals/chapter-06-near-real-time.md">不要频繁调用 <code>_refresh</code>，会产生大量小 Segment</li><li data-src-line="120" data-src-file="elasticsearch/05-distributed-internals/chapter-06-near-real-time.md">Translog 使用 <code>request</code> 模式保证数据安全</li><li data-src-line="121" data-src-file="elasticsearch/05-distributed-internals/chapter-06-near-real-time.md">监控 Segment 数量及其变化趋势，优先排查写入量与刷新频率；仅在合适的只读索引上评估 <code>_forcemerge</code></li><li data-src-line="122" data-src-file="elasticsearch/05-distributed-internals/chapter-06-near-real-time.md">生产环境接受 1s 的近实时延迟，不要为了实时性过度调优</li></ul>`,26)])])}const g=e(n,[["render",l]]);export{k as __pageData,g as default};
